// Host test for opl.h against the golden frames generated by the Python reference.
// Build & run:  c++ -std=c++17 -Wall -Wextra -Werror -I.. test_opl.cpp -o /tmp/test_opl && /tmp/test_opl frames.txt
#include "guard.h"
#include "opl.h"

#include <cassert>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

using namespace openbed::opl;

static std::vector<uint8_t> unhex(const std::string &s) {
  std::vector<uint8_t> out;
  if (s == "-")
    return out;
  for (size_t i = 0; i + 1 < s.size(); i += 2)
    out.push_back((uint8_t) std::stoi(s.substr(i, 2), nullptr, 16));
  return out;
}

static int failures = 0;
#define CHECK(c)                                              \
  do {                                                        \
    if (!(c)) {                                               \
      std::fprintf(stderr, "FAIL %s:%d %s\n", __FILE__, __LINE__, #c); \
      failures++;                                             \
    }                                                         \
  } while (0)

int main(int argc, char **argv) {
  CHECK(crc16_ccitt_false((const uint8_t *) "123456789", 9) == 0x29B1);

  std::ifstream in(argc > 1 ? argv[1] : "frames.txt");
  CHECK(in.good());
  std::string line;
  int n = 0;
  bool saw_telemetry = false;
  while (std::getline(in, line)) {
    if (line.empty() || line[0] == '#')
      continue;
    std::istringstream ls(line);
    int seq, type;
    std::string ph, wh;
    ls >> seq >> type >> ph >> wh;
    auto payload = unhex(ph), wire = unhex(wh);

    // encode must be byte-identical
    uint8_t out[MAX_WIRE];
    size_t w = encode((uint8_t) seq, (uint8_t) type, payload.data(), payload.size(), out, sizeof(out));
    CHECK(w == wire.size());
    CHECK(std::equal(wire.begin(), wire.end(), out));

    // decoding the wire bytes (with leading garbage + a corrupt frame) must yield exactly this frame
    StreamDecoder dec;
    Frame f{};
    int got = 0;
    for (uint8_t b : std::vector<uint8_t>{0x12, 0x34, 0x00})
      got += dec.push(b, f);
    CHECK(got == 0 && dec.errors == 1);
    for (uint8_t b : wire)
      got += dec.push(b, f);
    CHECK(got == 1);
    CHECK(f.seq == seq && f.type == type && f.len == payload.size());
    CHECK(std::equal(payload.begin(), payload.end(), f.payload));

    if (type == TELEMETRY) {
      Telemetry t{};
      CHECK(parse_telemetry(f.payload, f.len, t));
      CHECK(t.uptime_ms == 123456 && std::fabs(t.t_ambient - 23.0f) < 1e-4 && t.water_level_pct == 87);
      CHECK(std::fabs(t.sides[0].t_water - 21.5f) < 1e-4 && std::fabs(t.sides[0].tec_a - 3.2f) < 1e-4);
      CHECK(t.sides[1].faults == 0x0011 && t.sides[1].mode == 2);
      saw_telemetry = true;
    }
    n++;
  }
  CHECK(n >= 6 && saw_telemetry);

  // Roundtrip across COBS block boundaries (golden frames are all short).
  uint32_t x = 1;
  for (size_t len : {0u, 1u, 250u, 251u, 252u, 253u, 254u, 255u, 600u, 1019u}) {
    std::vector<uint8_t> pl(len);
    for (auto &v : pl) {
      x = x * 1103515245u + 12345u;
      v = (x >> 16) % 3 == 0 ? 0 : (uint8_t) (x >> 8);
    }
    uint8_t out[MAX_WIRE];
    size_t w = encode(42, SENSOR_BLOCK, pl.data(), pl.size(), out, sizeof(out));
    CHECK(w > 0);
    StreamDecoder dec;
    Frame f{};
    int got = 0;
    for (size_t i = 0; i < w; i++)
      got += dec.push(out[i], f);
    CHECK(got == 1 && f.len == len && std::equal(pl.begin(), pl.end(), f.payload));
  }
  // Oversized payload is rejected, not truncated.
  std::vector<uint8_t> big(MAX_BODY);
  uint8_t out2[MAX_WIRE];
  CHECK(encode(0, SENSOR_BLOCK, big.data(), big.size(), out2, sizeof(out2)) == 0);

  uint8_t p[4];
  set_target_payload(1, 21.5f, p);
  CHECK(p[0] == 1 && p[1] == 1 && rd_i16(p + 2) == 2150);
  set_target_payload(0, NAN, p);
  CHECK(p[1] == 0);

  // Dew-point guard: same cases as software/obc/tests/test_kits.py::test_dew_point_guard
  {
    using namespace openbed::guard;
    CHECK(std::fabs(dew_point_c(25.0f, 50.0f) - 13.86f) < 0.05f);
    CHECK(std::fabs(guarded_target(14.0f, 25.0f, 50.0f) - 14.86f) < 0.05f);
    CHECK(guarded_target(13.0f, 20.0f, 30.0f) == 13.0f);
    CHECK(guarded_target(14.0f, 28.0f, 90.0f) == 16.0f);
    CHECK(guarded_target(20.0f, 25.0f, 90.0f) == 20.0f);
    CHECK(guarded_target(14.0f, NAN, 50.0f) == 14.0f);
    CHECK(std::isnan(guarded_target(NAN, 25.0f, 50.0f)));
  }

  if (failures) {
    std::fprintf(stderr, "%d failure(s)\n", failures);
    return 1;
  }
  std::printf("opl.h: %d golden frames OK\n", n);
  return 0;
}
